def _region_delta_aggregate_rows(
    scenarios, elements, regions, data, weights, min_elements: int
) -> list[dict]:
    """Per-scenario/per-region aggregate rows in scenario-then-region order.

    Implements the aggregation described in :func:`aggregate_region_delta`
    for already-validated inputs: positive-weight elements whose row has
    ``state`` ``both`` are included and ``covered`` is their count; below
    ``min_elements`` the three stats are ``None``.  Raises ``ValueError``
    when an aggregated value is not finite.
    """
    n_elements = len(elements)
    n_regions = len(regions)
    rows = []
    for s_index, scenario in enumerate(scenarios):
        for r_index, region in enumerate(regions):
            included = []
            for e_index, weight in enumerate(weights):
                if weight <= 0:
                    continue
                row = data[
                    (s_index * n_elements + e_index) * n_regions + r_index
                ]
                if row["state"] == "both":
                    included.append((weight, row))
            covered = len(included)

            if covered < min_elements:
                rows.append(
                    {
                        "scenario": scenario,
                        "region": region,
                        "covered": covered,
                        "rank_change": None,
                        "magnitude": None,
                        "uncertainty": None,
                    }
                )
                continue

            max_weight = max(weight for weight, _row in included)
            coeffs = [weight / max_weight for weight, _row in included]
            coeff_total = math.fsum(coeffs)
            try:
                rank_change = (
                    math.fsum(
                        coeff * row["rank"]
                        for coeff, (_weight, row) in zip(
                            coeffs, included
                        )
                    )
                    / coeff_total
                )
                magnitude = (
                    math.fsum(
                        coeff * row["magnitude"]
                        for coeff, (_weight, row) in zip(
                            coeffs, included
                        )
                    )
                    / coeff_total
                )
                uncertainty = (
                    math.hypot(
                        *[
                            coeff * row["uncertainty"]
                            for coeff, (_weight, row) in zip(
                                coeffs, included
                            )
                        ]
                    )
                    / coeff_total
                )
            except OverflowError:
                raise ValueError(
                    "aggregated results must be finite"
                ) from None
            if not (
                _is_finite(rank_change)
                and _is_finite(magnitude)
                and _is_finite(uncertainty)
            ):
                raise ValueError("aggregated results must be finite")

            rows.append(
                {
                    "scenario": scenario,
                    "region": region,
                    "covered": covered,
                    "rank_change": _round_output(rank_change),
                    "magnitude": _round_output(magnitude),
                    "uncertainty": _round_output(uncertainty),
                }
            )

    return rows


